def bf(planet1, planet2):
    planets = ['Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune']
    distances = {'Mercury': 1, 'Venus': 2, 'Earth': 3, 'Mars': 4, 'Jupiter': 5, 'Saturn': 6, 'Uranus': 7, 'Neptune': 8}

    if planet1 not in planets or planet2 not in planets:
        return ()

    orbit1 = distances[planet1]
    orbit2 = distances[planet2]

    min_orbit = min(orbit1, orbit2)
    max_orbit = max(orbit1, orbit2)

    result = [planet for planet in planets if min_orbit < distances[planet] < max_orbit]
    return tuple(sorted(result, key=lambda x: distances[x]))

